    const canMembers=access.capabilities.includes("community.members.view"); const memberRows=canMembers?this.database.prepare(`SELECT m.user_id,u.display_name,m.status,m.discord_verified_at_utc,(SELECT max(e.occurred_at_utc) FROM traderlink_community_activity_events e WHERE e.community_id=m.community_id AND e.user_id=m.user_id) last_active,coalesce((SELECT json_group_array(r.name) FROM traderlink_community_member_role_assignments x JOIN traderlink_community_roles r ON r.role_id=x.role_id WHERE x.community_id=m.community_id AND x.user_id=m.user_id AND x.status='active'),'[]') roles FROM traderlink_community_memberships m JOIN platform_users u ON u.user_id=m.user_id WHERE m.community_id=? ORDER BY u.display_name`).all(community.community_id) as any[]:[];
