    const cutoff=new Date(Date.now()-30*86400000).toISOString().slice(0,10); const analyticsRow=access.capabilities.includes("community.analytics.view")?this.database.prepare(`SELECT coalesce(sum(views),0) views,count(DISTINCT user_id) users,coalesce(sum(CASE WHEN path LIKE '%/alerts%' THEN views ELSE 0 END),0) alert_views,coalesce(sum(CASE WHEN path LIKE '%/watchlists%' THEN views ELSE 0 END),0) watchlist_views,coalesce(sum(CASE WHEN path LIKE '%/coach%' THEN views ELSE 0 END),0) coaching_views FROM traderlink_community_activity_daily_members WHERE community_id=? AND activity_day>=?`).get(community.community_id,cutoff) as any:null; const topPages=access.capabilities.includes("community.analytics.view")?(this.database.prepare(`SELECT path,sum(views) views,count(DISTINCT user_id) users FROM traderlink_community_activity_daily_members WHERE community_id=? AND activity_day>=? GROUP BY path ORDER BY views DESC LIMIT 10`).all(community.community_id,cutoff) as any[]).map(r=>({path:r.path,views:r.views,uniqueMembers:r.users})):[];
